import{_ as d,o as e,c as a,ag as n}from"./chunks/framework.CD3EN-rd.js";const x=JSON.parse('{"title":"中国各省/直辖市/自治区 字面直译+官方标准译法对照表","description":"","frontmatter":{"order":2},"headers":[],"relativePath":"其他/冷知识/中国各省/中国各省字面直译 + 官方标准译法对照表.md","filePath":"其他/冷知识/中国各省/中国各省字面直译 + 官方标准译法对照表.md","lastUpdated":null}'),l={name:"其他/冷知识/中国各省/中国各省字面直译 + 官方标准译法对照表.md"};function r(i,t,h,o,s,g){return e(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="中国各省-直辖市-自治区-字面直译-官方标准译法对照表" tabindex="-1">中国各省/直辖市/自治区 字面直译+官方标准译法对照表 <a class="header-anchor" href="#中国各省-直辖市-自治区-字面直译-官方标准译法对照表" aria-label="Permalink to &quot;中国各省/直辖市/自治区 字面直译+官方标准译法对照表&quot;">​</a></h1><p>均为<strong>强行逐字字面直译</strong>（仅作趣味参考），<strong>所有正式场景一律使用官方标准译法</strong>（拼音/专属译法），部分省份直译会丢失地理本意，标注了得名由来补充说明。</p><h3 id="直辖市" tabindex="-1">直辖市 <a class="header-anchor" href="#直辖市" aria-label="Permalink to &quot;直辖市&quot;">​</a></h3><p>| 中文名称 | 官方标准译法 7| 字面强行直译 | | ---- | ---- | ---- 。| | 北京 | Beijing | North Capital | | 上海 | Shanghai | 无（专属地名，无逐字含义） | | 天津 | Tianjin | 无（专属地名，无逐字含义） | | 重庆 | Chongqing | Heavy Celebration |</p><h3 id="华北地区" tabindex="-1">华北地区 <a class="header-anchor" href="#华北地区" aria-label="Permalink to &quot;华北地区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文名称</th><th>官方标准译法</th><th>字面强行直译</th><th>补充说明</th></tr></thead><tbody><tr><td>河北</td><td>Hebei</td><td>North River</td><td>因位于黄河以北得名</td></tr><tr><td>山西</td><td>Shanxi</td><td>West Mountain</td><td>因位于太行山以西得名（注意：陕西为Shaanxi，区分拼音）</td></tr><tr><td>内蒙古</td><td>Inner Mongolia</td><td>Inner Mongolia</td><td>无强行直译，蒙语译音+通用表述</td></tr><tr><td>河南</td><td>Henan</td><td>South River</td><td>因位于黄河以南得名</td></tr><tr><td>山东</td><td>Shandong</td><td>East Mountain</td><td>因位于太行山以东得名</td></tr><tr><td>辽宁</td><td>Liaoning</td><td>Calm Peace</td><td>取“辽河流域永久安宁”之意，逐字直译无地理含义</td></tr></tbody></table><h3 id="华东地区" tabindex="-1">华东地区 <a class="header-anchor" href="#华东地区" aria-label="Permalink to &quot;华东地区&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">中文名称</th><th style="text-align:left;">官方标准译法</th><th style="text-align:left;">字面强行直译</th><th style="text-align:left;">补充说明</th></tr></thead><tbody><tr><td style="text-align:left;">江苏</td><td style="text-align:left;">Jiangsu</td><td style="text-align:left;">River Su</td><td style="text-align:left;">“江”指长江，“苏”为姑苏（苏州），直译丢失本意</td></tr><tr><td style="text-align:left;">浙江</td><td style="text-align:left;">Zhejiang</td><td style="text-align:left;">Zigzag River</td><td style="text-align:left;">本名“折江”，因钱塘江河道曲折得名，直译贴合本意</td></tr><tr><td style="text-align:left;">安徽</td><td style="text-align:left;">Anhui</td><td style="text-align:left;">An Hui</td><td style="text-align:left;">取安庆、徽州首字，无逐字直译含义</td></tr><tr><td style="text-align:left;">福建</td><td style="text-align:left;">Fujian</td><td style="text-align:left;">Fu Jian</td><td style="text-align:left;">取福州、建州首字，无逐字直译含义</td></tr><tr><td style="text-align:left;">江西</td><td style="text-align:left;">Jiangxi</td><td style="text-align:left;">West River</td><td style="text-align:left;">因位于江南西道得名，“江”指长江，非单纯“西方的江”</td></tr><tr><td style="text-align:left;">山东</td><td style="text-align:left;">Shandong</td><td style="text-align:left;">East Mountain</td><td style="text-align:left;">重复，见华北区。</td></tr><tr><td style="text-align:left;">上海</td><td style="text-align:left;">Shanghai</td><td style="text-align:left;">无（专属译音）</td><td style="text-align:left;">重复，见直辖市。</td></tr><tr><td style="text-align:left;">台湾</td><td style="text-align:left;">Taiwan</td><td style="text-align:left;">无（专属译音）</td><td style="text-align:left;">正式表述：中国台湾（Taiwan, China）</td></tr></tbody></table><h3 id="华中地区" tabindex="-1">华中地区 <a class="header-anchor" href="#华中地区" aria-label="Permalink to &quot;华中地区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文名称</th><th>官方标准译法</th><th>字面强行直译</th><th>补充说明</th></tr></thead><tbody><tr><td>湖北</td><td>Hubei</td><td>North Lake</td><td>因位于洞庭湖以北得名，直译贴合本意</td></tr><tr><td>湖南</td><td>Hunan</td><td>South Lake</td><td>因位于洞庭湖以南得名，直译贴合本意</td></tr><tr><td>河南</td><td>Henan</td><td>South River</td><td>重复，见华北区</td></tr></tbody></table><h3 id="华南地区" tabindex="-1">华南地区 <a class="header-anchor" href="#华南地区" aria-label="Permalink to &quot;华南地区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文名称</th><th>官方标准译法</th><th>字面强行直译</th><th>补充说明</th></tr></thead><tbody><tr><td>广东</td><td>Guangdong</td><td>East Wide</td><td>“广”指广信县，取“广信以东”，直译丢失本意</td></tr><tr><td>广西</td><td>Guangxi</td><td>West Wide</td><td>取“广信以西”，直译丢失本意，正式全称：Guangxi Zhuang Autonomous Region</td></tr><tr><td>海南</td><td>Hainan</td><td>South Sea</td><td>因位于南海之中得名，直译贴合本意</td></tr><tr><td>香港</td><td>Hong Kong</td><td>无（专属译音）</td><td>正式表述：Hong Kong, China</td></tr><tr><td>澳门</td><td>Macao/Macau</td><td>无（专属译音）</td><td>正式表述：Macao, China</td></tr></tbody></table><h3 id="西南地区" tabindex="-1">西南地区 <a class="header-anchor" href="#西南地区" aria-label="Permalink to &quot;西南地区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文名称</th><th>官方标准译法</th><th>字面强行直译</th><th>补充说明</th></tr></thead><tbody><tr><td>四川</td><td>Sichuan</td><td>Four Rivers</td><td>因境内岷江、沱江、嘉陵江、长江四条大河得名，直译贴合本意</td></tr><tr><td>贵州</td><td>Guizhou</td><td>Expensive State</td><td>“贵”为古地名，无“昂贵”含义，直译易产生歧义</td></tr><tr><td>云南</td><td>Yunnan</td><td>South Cloud</td><td>因位于“云岭之南”得名，直译贴合字面（非实际云朵）</td></tr><tr><td>西藏</td><td>Xizang/Tibet</td><td>West Tibet</td><td>官方标准译法：Xizang（拼音），Tibet为国际通用译法，正式全称：Xizang Autonomous Region of China</td></tr><tr><td>重庆</td><td>Chongqing</td><td>Heavy Celebration</td><td>重复，见直辖市</td></tr></tbody></table><h3 id="西北地区" tabindex="-1">西北地区 <a class="header-anchor" href="#西北地区" aria-label="Permalink to &quot;西北地区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文名称</th><th>官方标准译法</th><th>字面强行直译</th><th>补充说明</th></tr></thead><tbody><tr><td>陕西</td><td>Shaanxi</td><td>West Mountain</td><td>因位于陕原以西得名，拼音加a区分山西（Shanxi），直译易混淆</td></tr><tr><td>甘肃</td><td>Gansu</td><td>Gan Su</td><td>取甘州、肃州首字，无逐字直译含义</td></tr><tr><td>青海</td><td>Qinghai</td><td>Blue Sea/Green Sea</td><td>因青海湖得名，直译贴合本意</td></tr><tr><td>宁夏</td><td>Ningxia</td><td>Peaceful Summer</td><td>取“西夏安宁”之意，直译无地理含义</td></tr><tr><td>新疆</td><td>Xinjiang</td><td>New Border/New Territory</td><td>直译贴合本意，正式全称：Xinjiang Uygur Autonomous Region</td></tr></tbody></table><h3 id="东北地区" tabindex="-1">东北地区 <a class="header-anchor" href="#东北地区" aria-label="Permalink to &quot;东北地区&quot;">​</a></h3><table tabindex="0"><thead><tr><th>中文名称</th><th>官方标准译法</th><th>字面强行直译</th><th>补充说明</th></tr></thead><tbody><tr><td>黑龙江</td><td>Heilongjiang</td><td>Black Dragon River</td><td>因黑龙江得名，直译贴合本意（国际通用：Amur River，江名）</td></tr><tr><td>吉林</td><td>Jilin</td><td>Lucky Forest</td><td>“吉林”为满语译音，取“沿江之地”，直译无实际含义</td></tr><tr><td>辽宁</td><td>Liaoning</td><td>Calm Peace</td><td>重复，见华北区</td></tr></tbody></table>',18)])])}const b=d(l,[["render",r]]);export{x as __pageData,b as default};
